}

function themify_clear_all_html(){
    check_ajax_referer('tf_nonce', 'nonce');
    if ( ! current_user_can( 'manage_options' ) ) {
        die;
    }
    $type='blog';
    if(is_multisite()){
        $data = themify_normalize_save_data($_POST['data']);
        if(!empty($data['tmp_cache_network'])){
            $type='all';
        }
        $data=null;
    }
    TFCache::remove_cache($type);
    die('1');
}
